<?php require __DIR__.'/../app/bootstrap.php';admin_required();$id=(int)($_GET['id']??0);$p=['name'=>'','slug'=>'','category_id'=>'','price'=>'','stock'=>0,'description'=>'','status'=>'active','image'=>null];if($id){$s=db()->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch()?:$p;}$categories=db()->query('SELECT id,name FROM categories ORDER BY sort_order,name')->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$slug=trim($_POST['slug']??'');if($slug==='')$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-'));$category=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$stock=max(0,(int)($_POST['stock']??0));$desc=trim($_POST['description']??'');$status=($_POST['status']??'active')==='draft'?'draft':'active';$image=$p['image']??null;if(!$name||$price<0){$error='Product name and a valid price are required.';}else{if(!empty($_FILES['image']['name'])){$f=$_FILES['image'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>4*1024*1024){$error='Image upload failed or file is larger than 4MB.';}else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))$error='Only JPG, PNG and WEBP images are allowed.';else{$dir=__DIR__.'/../uploads/products';if(!is_dir($dir))mkdir($dir,0755,true);$image=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$image))$error='Could not save image.';}}}if(!$error){if($id){$s=db()->prepare('UPDATE products SET name=?,slug=?,category_id=?,price=?,stock=?,description=?,status=?,image=? WHERE id=?');$s->execute([$name,$slug,$category?:null,$price,$stock,$desc,$status,$image,$id]);}else{$s=db()->prepare('INSERT INTO products(name,slug,category_id,price,stock,description,status,image) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$name,$slug,$category?:null,$price,$stock,$desc,$status,$image]);}header('Location: '.url('admin/products.php?saved=1'));exit;}}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $id?'Edit':'Add' ?> Product</title><link rel="stylesheet" href="<?=e(url('assets/css/style.css'))?>"></head><body class="admin-body"><aside class="admin-sidebar"><a class="wordmark" href="<?=e(url('admin/index.php'))?>"><span>NEXT</span> <b>TECH</b></a><a href="<?=e(url('admin/index.php'))?>">Dashboard</a><a class="active" href="<?=e(url('admin/products.php'))?>">Products</a><a href="<?=e(url('admin/categories.php'))?>">Categories</a><a href="<?=e(url('admin/logout.php'))?>">Logout</a></aside><main class="admin-main"><div class="admin-top"><h1><?= $id?'Edit Product':'Add Product' ?></h1></div><form class="admin-panel form-grid" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php if($error): ?><p class="form-error full"><?=e($error)?></p><?php endif; ?><label>Product Name<input name="name" required value="<?=e($p['name'])?>"></label><label>URL Slug<input name="slug" value="<?=e($p['slug'])?>" placeholder="auto-generated if blank"></label><label>Category<select name="category_id"><option value="">Select category</option><?php foreach($categories as $c): ?><option value="<?=(int)$c['id']?>" <?=((int)$p['category_id']===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select></label><label>Price (BDT)<input type="number" name="price" min="0" step="0.01" required value="<?=e((string)$p['price'])?>"></label><label>Stock Quantity<input type="number" name="stock" min="0" required value="<?=e((string)$p['stock'])?>"></label><label>Status<select name="status"><option value="active" <?=$p['status']==='active'?'selected':''?>>Active</option><option value="draft" <?=$p['status']==='draft'?'selected':''?>>Draft</option></select></label><label class="full">Description<textarea name="description" rows="5"><?=e($p['description'])?></textarea></label><label class="full">Product Image (JPG/PNG/WEBP, max 4MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><?php if($p['image']): ?><p class="full">Current image: <?=e($p['image'])?></p><?php endif; ?><div class="full"><button class="btn btn-primary">Save Product</button></div></form></main></body></html>
